package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.database.Cursor;import android.provider.*;import java.io.*;import java.util.*;
/** Bounded, on-demand search. Does not persist SMS, calendar text or a filesystem index. */
final class ExtendedSearch {
 static void append(Context c,String term,ArrayList<GlobalSearchActivity.Hit> out){sms(c,term,out);calendar(c,term,out);files(c,term,out);}
 static void sms(Context c,String term,ArrayList<GlobalSearchActivity.Hit> out){HashSet<String> seen=new HashSet<String>();int added=0;
  try(Cursor r=c.getContentResolver().query(Telephony.Sms.CONTENT_URI,new String[]{"address","body","date"},null,null,"date DESC")){int n=0;while(r!=null&&r.moveToNext()&&n++<1500&&added<20)if(addSms(c,term,r.getString(0),r.getString(1),r.getLong(2),seen,out))added++;}catch(RuntimeException ignored){}
  if(added>=20)return;try(SmsStore db=new SmsStore(c)){for(String table:new String[]{"inbox","outgoing"})try(Cursor r=db.getReadableDatabase().query(table,new String[]{"address","body","date"},null,null,null,null,"date DESC","1500")){while(r.moveToNext()&&added<20)if(addSms(c,term,r.getString(0),r.getString(1),r.getLong(2),seen,out))added++;}}catch(RuntimeException ignored){}
 }
 static boolean addSms(Context c,String term,String address,String body,long date,Set<String> seen,ArrayList<GlobalSearchActivity.Hit> out){if(address==null||body==null||ConversationPrefs.has(c,"blocked",address)||!GlobalSearchActivity.matches(address+" "+body,term)||!seen.add(ConversationPrefs.key(address)+"|"+body))return false;String preview=body.replace('\n',' ');out.add(new GlobalSearchActivity.Hit("SMS · "+address+"\n"+preview.substring(0,Math.min(70,preview.length())),new Intent(c,MessagesActivity.class).putExtra("thread",address).putExtra("search_date",date)));return true;}
 static void calendar(Context c,String term,ArrayList<GlobalSearchActivity.Hit> out){try{long own=CalendarReminders.calendar(c),now=System.currentTimeMillis();if(own<0)return;try(Cursor r=c.getContentResolver().query(CalendarReminders.instances(now-30L*86400000,now+366L*86400000),new String[]{"event_id","begin","title","description"},"calendar_id=?",new String[]{""+own},"begin ASC")){int scanned=0,added=0;while(r!=null&&r.moveToNext()&&scanned++<1500&&added<20)if(GlobalSearchActivity.matches(r.getString(2)+" "+r.getString(3),term)){out.add(new GlobalSearchActivity.Hit("Calendar · "+r.getString(2)+"\n"+android.text.format.DateFormat.format("dd.MM.yyyy HH:mm",r.getLong(1)),new Intent(c,CalendarActivity.class).putExtra("day",r.getLong(1)).putExtra("event_id",r.getLong(0))));added++;}}}catch(RuntimeException ignored){}}
 static void files(Context c,String term,ArrayList<GlobalSearchActivity.Hit> out){for(File f:findFiles(new ArrayList<File>(LeoFileProvider.roots(c).values()),term)){out.add(new GlobalSearchActivity.Hit(L.t("Fișier · ")+f.getName(),new Intent(c,FilesActivity.class).putExtra("folder",f.getParent()).putExtra("select_file",f.getAbsolutePath())));}}
 static ArrayList<File> findFiles(List<File> roots,String term){ArrayList<File> result=new ArrayList<File>();HashSet<String> seen=new HashSet<String>();int scanned=0;for(File boundary:roots){ArrayDeque<File> queue=new ArrayDeque<File>();queue.add(boundary);while(!queue.isEmpty()&&scanned<3000&&result.size()<20){File directory=queue.removeFirst();try{String path=directory.getCanonicalPath();if(!LeoFileProvider.inside(boundary,directory)||!seen.add(path))continue;File[] entries=directory.listFiles();if(entries==null)continue;for(File f:entries){if(++scanned>3000||result.size()>=20)break;if(!LeoFileProvider.inside(boundary,f)||f.getName().startsWith("."))continue;if(f.isFile()&&GlobalSearchActivity.matches(f.getName(),term))result.add(f);else if(f.isDirectory()&&!f.getName().equals("Android")&&queue.size()<64&&f.getCanonicalPath().substring(boundary.getCanonicalPath().length()).split("/").length<=5)queue.add(f);}}catch(IOException|SecurityException ignored){}}}return result;}
}
